test("denial date counts as day 0", function () {
  var result = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-10" });
  assert.deepEqual(result, { allowed: true, daysLeft: 120, elapsedDays: 0 });
});

test("appeal allowed inside the window", function () {
  var result = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-03-10" });
  assert.deepEqual(result, { allowed: true, daysLeft: 61, elapsedDays: 59 });
});

test("day 120 inclusive still allowed", function () {
  var result = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-10" });
  assert.deepEqual(result, { allowed: true, daysLeft: 0, elapsedDays: 120 });
});

test("elapsed days over 120 is closed", function () {
  var result = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-11" });
  assert.deepEqual(result, { allowed: false, daysLeft: 0, elapsedDays: 121 });
});

test("status is explicit when days left is 0", function () {
  var lastDay = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-10" });
  var after = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-11" });
  assert.equal(lastDay.allowed, true);
  assert.equal(lastDay.daysLeft, 0);
  assert.equal(after.allowed, false);
  assert.equal(after.daysLeft, 0);
});

test("days left is 120 minus elapsed days when allowed else 0", function () {
  var day0 = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-10" });
  var day59 = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-03-10" });
  var day120 = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-10" });
  var day121 = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-11" });
  assert.equal(day0.elapsedDays, 0);
  assert.equal(day0.daysLeft, 120 - day0.elapsedDays);
  assert.equal(day59.elapsedDays, 59);
  assert.equal(day59.daysLeft, 120 - day59.elapsedDays);
  assert.equal(day120.elapsedDays, 120);
  assert.equal(day120.daysLeft, 120 - day120.elapsedDays);
  assert.equal(day121.elapsedDays, 121);
  assert.equal(day121.daysLeft, 0);
});

test("check date earlier than denial date is rejected", function () {
  assert.throws(function () {
    code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-09" });
  }, /checkDate is before denialDate/);
});
